876	                  onChange={(e) => setNewObs(e.target.value)}
877	                />
878	              </div>
879	            )}
880	
881	            {/* Quantidade + Unidade */}
882	            <div className="grid grid-cols-2 gap-3">
883	              <div>
884	                <Label className="text-xs text-muted-foreground">Quantidade</Label>
885	                <Input
886	                  type="number"
887	                  className="mt-1"
888	                  value={newQty}
889	                  onChange={(e) => setNewQty(e.target.value)}
890	                />
891	              </div>
892	              <div>
893	                <Label className="text-xs text-muted-foreground">Unidade</Label>
894	                <Input
895	                  className="mt-1"
896	                  placeholder="un, kg, cx..."
897	                  value={newUnit}
898	                  onChange={(e) => setNewUnit(e.target.value)}
899	                />
900	              </div>
901	            </div>
902	
903	            {/* Preço unitário: só para custo avulso */}
904	            {newTipo === 'outro' && (
905	              <div>
906	                <Label className="text-xs text-muted-foreground">Preço unitário (esboço)</Label>
907	                <Input
908	                  type="number"
909	                  step="0.01"
910	                  className="mt-1"
911	                  placeholder="0,00"
912	                  value={newPreco}
913	                  onChange={(e) => setNewPreco(e.target.value)}
914	                />
915	              </div>
916	            )}
917	          </div>
918	
919	          <DialogFooter>
920	            <Button variant="outline" onClick={() => setIsAddOpen(false)}>
921	              Cancelar
922	            </Button>
923	            <Button
924	              className="bg-[#57715B] hover:bg-[#465b49] text-white"
925	              onClick={handleAddItem}
926	              disabled={
927	                isAddSaving ||
928	                (newTipo === 'embalagem' && !newInsumoId) ||
929	                (newTipo === 'outro' && !newObs.trim())
930	              }
931	            >
932	              {isAddSaving ? <Loader2 size={14} className="animate-spin mr-1" /> : <Plus size={14} className="mr-1" />}
933	              Adicionar
934	            </Button>
935	          </DialogFooter>
936	        </DialogContent>
937	      </Dialog>
938	    </div>
939	  );
940	}
